// The docs site's generated files, so its pages can't drift from the app:
//  - apps/docs/lib/generated/shortcuts.json: the shortcut sheet, the keymaps' swaps, the macOS
//    menu bar and every ⌘K command, read from the commands.ts registry as a Mac shows them;
//  - apps/docs/lib/generated/releases.json: docs/releases/v*.md, newest first, for the Release
//    notes page (the docs build can't read outside apps/docs on Vercel).
// `npm test` fails when either is stale; `UPDATE_DOCS=1 npx vitest run test/docs-generated.test.ts`
// rewrites them. (The MCP tool table is generated by rowkery-mcp's docs_table test.)
import { expect, test } from "vitest";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { COMMANDS, chordFor, formatChord, menuSpec, sheetRows, type CommandState } from "../src/commands";
import { KEYMAPS, KEYMAP_CHORDS } from "../src/keymaps";

const GENERATED = fileURLToPath(new URL("../../docs/lib/generated/", import.meta.url));
const RELEASES = fileURLToPath(new URL("../../../docs/releases/", import.meta.url));
const fresh = { sidebarHidden: false } as CommandState;
const byId = new Map(COMMANDS.map((c) => [c.id, c]));
const title = (id: string) => {
  const t = byId.get(id)!.title;
  return typeof t === "function" ? t(fresh) : t;
};
const keys = (id: string, keymap: "rowkery" | "tableplus" | "datagrip" = "rowkery") => {
  const chord = chordFor(byId.get(id)!, keymap);
  return chord ? formatChord(chord, true) : "";
};

function tables() {
  return {
    sections: sheetRows("rowkery", true).map(({ name, rows }) => ({ name, rows: rows.map((r) => ({ title: r.title, keys: r.keys })) })),
    keymaps: KEYMAPS.filter((k) => k.id !== "rowkery").map((k) => ({
      label: k.label,
      swaps: Object.keys(KEYMAP_CHORDS[k.id]).map((id) => ({ title: title(id), rowkery: keys(id), keys: keys(id, k.id) })),
    })),
    menus: menuSpec().map((m) => ({
      menu: m.submenu,
      items: m.items.flatMap((i) => ("separator" in i ? [] : [{ title: i.title, keys: keys(i.id) }])),
    })),
    palette: COMMANDS.filter((c) => c.palette !== false && !c.planned).map((c) => ({ title: title(c.id), keys: keys(c.id) })),
  };
}

/** v0.10.0 after v0.9.1: compare the numbers. */
const version = (f: string) => f.replace(/^v|\.md$/g, "").split(".").map(Number);
function releases() {
  return readdirSync(RELEASES)
    .filter((f) => /^v\d+\.\d+\.\d+\.md$/.test(f))
    .sort((a, b) => {
      const [x, y] = [version(a), version(b)];
      return y[0] - x[0] || y[1] - x[1] || y[2] - x[2];
    })
    .map((f) => ({ version: f.replace(/\.md$/, ""), markdown: readFileSync(RELEASES + f, "utf8") }));
}

for (const [file, make] of [
  ["shortcuts.json", tables],
  ["releases.json", releases],
] as const) {
  test(`apps/docs/lib/generated/${file} is up to date`, () => {
    const want = `${JSON.stringify(make(), null, 2)}\n`;
    if (process.env.UPDATE_DOCS) writeFileSync(GENERATED + file, want);
    expect(readFileSync(GENERATED + file, "utf8"), "run UPDATE_DOCS=1 npx vitest run test/docs-generated.test.ts").toBe(want);
  });
}
